#!/bin/bash
# usage: cache-brief.sh <agent> <worktree> <branch> <prog> <specpage>
B="You are a worker on the Mo language project, in the worktree $2 (branch $3). Zig is on PATH through mise; the toolchain binary is toolchain/zig-out/bin/mo (never run zig build; never run zig build test). Read examples/README.md first. Every function body in examples/programs/$4/ is gone: each module keeps its intent, types, processes, signatures with their contracts, and its tests as written; the program's spec is mo-wiki/spec/programs/$5.md. Your one task: write every body, and any private helper you need, so that 'mo check' and 'mo test' are green on every module of the program, every '# run:' line at the top of main.mo prints its .expected file byte for byte (run them with 'mo run main.mo -- <args>' from the program folder and diff against the .expected files, the first run against $4.expected, the second against $4-2.expected, and so on; '# exit:' lines give the expected exit code), and 'mo test --write' has rewritten the verified: lines. Leave the tests as they are; touch no other program. Put a timeout on every mo process you run (timeout 120), and a memory watchdog: kill any mo process past 4 GB. Never use tr (aliased; use python3). Keep a count of your loops: every time mo check or mo test or a run fails, note the diagnostic code or the failing test and whether your next edit fixed it. Commit when green with subject '$4 regenerated' and the trailer 'Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>'; do not push. Do not stop early; stop at Done-when with the wall-clock, the loop count by cause (and whether the first fix worked), and a numbered list 'Decisions the spec did not cover', and write that same report to REPORT-$4.md at the worktree root."
herdr agent prompt "$1" "$B" 2>&1 | python3 -c "import json,sys; print(json.load(sys.stdin)['result']['type'])"
